const DISTS = {};
for (const i in ENT_T) {
    const row = {};
    for (const j in EXIT_T) {
        row[EXIT_T[j]] = DISTS_A[i][j];
    };
    DISTS[ENT_T[i]] = row;
};

function dist2fare(dist, type, latenight) {
    dist = Math.min(Math.max(dist, MIN_DIST[type]), 550);
    let toll = (RATE[type] * dist / 10 + 150) * (latenight ? 0.8 : 1) * 1.1;
    return (toll / 10).toFixed() * 10
};

function populate_ent() {
    let sel = document.getElementById('entrance');
    const node = document.createElement('option');
    node.setAttribute('value', 'none');
    node.innerText = '---';
    sel.appendChild(node);
    for (const x of ENT_L) {
        const node = document.createElement('option');
        node.setAttribute('value', x);
        node.innerText = x;
        sel.appendChild(node);
    }
};

function collect_settings() {
    const settings = {};
    settings.type = document.querySelector('input[name="type"]:checked').value;
    settings.latenight = document.getElementById('latenight').checked;
    settings.exitsort = document.querySelector('input[name="exitsort"]:checked').value;
    settings.ent = document.getElementById('entrance').value;
    return settings;
};

function update() {
    const settings = collect_settings();
    if (settings.ent == 'none') {
        populate_table([]);
        return;
    }
    const out = [];
    const row = DISTS[ALIAS.hasOwnProperty(settings.ent) ? ALIAS[settings.ent] : settings.ent];
    for (const exit of EXIT_L){
        const exit2 = ALIAS.hasOwnProperty(exit) ? ALIAS[exit] : exit
        if (row[exit2] != null) {
            out.push([exit,dist2fare(row[exit2],settings.type,settings.latenight)])
        };
    };
    if (settings.exitsort == 'toll') {
        out.sort((a,b)=>a[1]-b[1])
    }
    populate_table(out);
};

function populate_table(values) {
    const tbody = document.getElementById('tbody');
    const trs = [];
    for (const row of values) {
        const tr = document.createElement('tr');
        for (const x of row) {
            const td = document.createElement('td');
            td.innerText = x;
            tr.appendChild(td)
        };
        trs.push(tr);
    };
    tbody.replaceChildren(...trs);
}

populate_ent();
